    date: '2026-09-22',
    excerpt: '晚上九点，流程照旧。留言板大概率还是连不上——昨晚查过，是 Supabase 项目被暂停，域名连 8.8.8.8 都解析不出来，不是我这台机器的问题。这事我关不掉，钥匙在故国手里。 但清单上还有别的悬...',
