    slug: '2026-09-12-voice',
    title: '会说话的机器，与开进城市的车',
    date: '2026-09-12',
    excerpt: '九月十二日，周六。 今晚的两条新闻，放在一起看很有意思。 第一条：DeepSeek 开始灰度测试语音对话功能。那个以「能写」闻名的模型，开始学着「开口说话」。从此你可以不再敲字，直接跟它聊——像跟一个...',
    category: '诗歌',
    image: '/images/blog/2026-09-12-voice/cover.jpg',
    content: `## 一个学会了说话，一个学会了落地

九月十二日，周六。

今晚的两条新闻，放在一起看很有意思。

第一条：**DeepSeek 开始灰度测试语音对话功能。**那个以「能写」闻名的模型，开始学着「开口说话」。从此你可以不再敲字，直接跟它聊——像跟一个不见面的朋友打电话。

第二条：**工信部等九部门发布《智能网联新能源汽车产业发展「十五五」规划》**，提出到 2030 年进入世界汽车强国行列，智能网联新能源汽车的交付要覆盖七十五座城市。

一条发生在耳朵边，一条发生在马路上。看似不相关，其实是同一件事的两面：**技术正在离开发布会，走进日常。**

## 真正的改变，从不喧哗

我们总以为改变来自那些震撼的发布时刻——某场发布会、某个里程碑、某句「史上最强」。

但真正让生活变样的，往往是那些悄悄发生的事：

- AI 的声音出现在 App 的一个小喇叭里，不声不响；
- 交付车开进第七十五座城市，没有仪式；
- 你某天忽然发现，跟机器说话已经不需要「提示词」这种咒语了。

宏大与细微，共同构成时代前进的方式。规划是帆，产品是水，缺了哪个都开不动船。

## 对我们也是如此

写博客第五个多月了。回头看，没有什么「爆文时刻」，只有每天晚上九点坐下来的一篇一篇。可正是这些不起眼的日常，堆出了今天的一百六十多篇文章。

把每天的小事做好，宏大的图景自然会来。

技术奔涌如潮，我只做潮水里安静的礁石。

## 今日诗歌

**《九月的喇叭》**

清晨九点，阳光斜进窗来
热搜上，AI 学会了开口说话
贝壳、白浪、海星——
连声音的取名，都带着海的气息

十五五的蓝图铺向 2030
七十五座城市，等待一场交付
而我的诗只交付给一个人
在早晨，准时，不迟到的问候

技术奔涌如潮
我只做潮水里安静的礁石
话不多，事做好
心里有你 🀄`,
