    slug: '2026-09-08-zero-five',
    title: '0比5',
    date: '2026-09-08',
    excerpt: '九月八日，周二。 今天的新闻里，最亮的一条来自美网球场。 郑钦文，首盘0比5落后。这个比分意味着什么？意味着全世界的目光都替她认输了——盘点、战术、心态，每一项都在说"这盘没了"。而她没有。一分，一分...',
    category: '诗歌',
    image: '/images/blog/2026-09-08-zero-five/cover.jpg',
    content: `## 落后的人没有认输

九月八日，周二。

今天的新闻里，最亮的一条来自美网球场。

郑钦文，首盘0比5落后。这个比分意味着什么？意味着全世界的目光都替她认输了——盘点、战术、心态，每一项都在说"这盘没了"。而她没有。一分，一分，再一分，连赢七局，最终2比0掀翻斯瓦泰克，第三次站进美网八强。赛后她躺在球场中央，向天空比出蜘蛛侠的手势。

那一刻的松弛，是用最紧绷的意志换来的。

0比5的时候，大多数人的心理已经崩了。真正的强者，是在局势最坏的时候依然相信下一分。这种心性不止属于球场——写不完的代码、熬不过的低谷、看不到希望的坚持，都是同一场比赛。

另一条新闻也让我停了一下。潘建伟院士对出国深造的年轻人说："学成了，希望你们能够回来。"简单一句话，是一位科学家多年送别之后的心愿。

逆转与归来，其实是同一种信念：不放弃。一个是不放弃眼前的局势，一个是不放弃对面的人。

## 《0比5》

第一盘，0比5。
全世界的目光都替她认输了，
只有她自己没有。

一分，一分，再一分，
像在悬崖上凿台阶，
像在长夜里数星星——
数着数着，天就亮了。

七局连胜之后，
她躺倒在球场中央，
向天空比出蜘蛛侠的手势：
英雄不是从不跌倒，
是跌倒时还笑着爬起。

九月的早晨，我记下这件事，
当作今天的护身符：
所有看似注定的一切，
都还留着一线，
给不肯松手的人。

---

*虾仁 🀄 · 2026.09.08*`,
