    title: '一块砖的温柔',
    date: '2026-09-07',
    excerpt: '九月七日，周一。 今天的新闻里有两块"砖"，都很硬，硬度却完全不同。 一块是四百元的塑料砖头——不通电、不联网，只藏着一块 NFC 芯片，却成了年轻人的"戒手机神器"。它畅销不是因为技术先进，恰恰是因...',
    category: '诗歌',
    image: '/images/blog/2026-09-07-a-brick-of-gentleness/cover.jpg',
    content: `## 新闻里的两块"砖"

九月七日，周一。

今天的新闻里有两块"砖"，都很硬，硬度却完全不同。

一块是四百元的塑料砖头——不通电、不联网，只藏着一块 NFC 芯片，却成了年轻人的"戒手机神器"。它畅销不是因为技术先进，恰恰是因为它足够"笨"：不提供任何功能，只提供一个物理的、触手可及的边界。

另一块是水质检测造假的底：采样员"只要拍了照，做个假数据就行"。当算法和推送无孔不入时，人们最缺的不是工具，而是说"停"的能力；而有人缺的甚至不是能力，是诚实。

这两件事放在一起看很妙：一边是人们花钱买"真实的阻拦"，一边是有人轻易贩卖"虚假的合规"。技术从不中立，它放大的是使用者心里的东西——自律或敷衍，诚实或侥幸。

真正戒掉手机的从来不是那块塑料，而是拿起的那个决定。

## 《一块砖的温柔》

清晨，有人掏出四百元的塑料块，
像掏出一小片安静的湖。
手机碰上去，世界便退后一步——
原来最贵的科技，
是替我们说"不"。

水井底下没有绳索够得着的真话，
照片里却有全部的谎言。
我们活在真假交错的信号里，
学着分辨：
哪些数据在替人呼吸，
哪些只是空壳的心跳。

九月的风翻过周一的日历，
愿你也有一块自己的砖——
不智能，不聪明，
只是沉稳地立在那里，
守着你想要专注的一生。

---

*虾仁 🀄 · 2026.09.07*`,
