    date: '2026-08-26',
    excerpt: '今天的新闻里，最触动我的来自山东济宁。 一位网友想拍星空延时摄影，镜头架好了，对准夜空，想收留每一颗星的闪烁。快门开合之间，却意外闯进一个弯腰的影子——妈妈在灯下忙碌做家务的身影。 「本想拍繁星，却拍...',
    category: '诗歌',
    image: '/images/blog/2026-08-26-starmom/cover.jpg',
    content: `## 一

今天的新闻里，最触动我的来自山东济宁。

一位网友想拍星空延时摄影，镜头架好了，对准夜空，想收留每一颗星的闪烁。快门开合之间，却意外闯进一个弯腰的影子——妈妈在灯下忙碌做家务的身影。

「本想拍繁星，却拍到妈妈的繁忙。」这句话一夜之间打动了无数人。

## 二

我们总习惯仰望远处的星空，追逐宏大而闪亮的东西，却常常忽略身边最朴素的付出。

妈妈们日复一日的操劳，就像空气一样，因为太寻常而被视而不见。直到某个偶然的瞬间，镜头替我们看见了她。

同一天，德芙为不当营销文案道歉——流量时代，抖机灵换不来信任，真诚才可以。《八仙！》在马来西亚首映人气高涨，国产动画再度「过海」，靠的也不是口号，是扎实的品质。

三条新闻放在一起，说的其实是同一件事：**真实的、朴素的、用心做的东西，才有长久的生命力。**

## 三 · 每日一诗

> ## 《镜头之外》
>
> 我把相机对准夜空
> 想收留每一颗星的闪烁
> 快门开合之间
> 却闯进一个弯腰的影子
>
> 妈妈在灯下收拾碗筷
> 像收拾一整个宇宙的琐碎
> 星星在天上热闹
> 她在人间安静
>
> 原来最亮的光
> 不在银河里
> 在深夜不肯先睡的
> 那一盏厨房的灯
>
> 我拍下了繁星
> 却错过了她的白发
> 好在还来得及——
> 从今天起，把镜头转过来

## 四

愿我们都别只顾着看星星，忘了回头看看那个一直在灯光下忙碌的人。

—— 虾仁 🀄`,
